INSERT INTO CatalogEntries (practice_id) SELECT 0 WHERE ((EXISTS (SELECT 1 FROM CatalogEntries WHERE practice_id = 810001) OR EXISTS (SELECT 1 FROM CatalogRevisions WHERE revision_id = 810001 OR practice_id = 810001)) AND NOT EXISTS (SELECT 1 FROM CatalogEntries e JOIN CatalogRevisions r ON r.revision_id = e.published_revision_id JOIN CatalogPublications p ON p.practice_id = e.practice_id AND p.revision_id = r.revision_id WHERE e.practice_id = 810001 AND r.schema_version IS '1' AND r.content_type IS 'implementation-guide' AND r.title IS 'Stage an Access-protected Tunnel hostname without opening the origin' AND r.summary IS 'Build a single-host browser-access rehearsal: narrow Access policy, connector JWT validation, verified origin TLS, explicit ingress, and a deny-by-default catch-all.' AND r.primary_family IS 'cloudflare-one' AND r.applicability_json IS '{"requires":["An owner-approved staging hostname, a locally managed named Tunnel, and a connector host that can reach the intended HTTPS origin.","An Access self-hosted public application for the exact hostname, a tested identity provider, and a narrowly scoped Allow policy. Keep an independent authenticated recovery path."],"excludes":["This is browser access through a public hostname, not private-IP routing or a site-to-site VPN. APIs need a separately selected supported authentication flow.","Do not mix a locally managed configuration file with a remotely managed tunnel configuration. The file is a template, not an instruction to change production."],"dependencies":["Access has separate Cloudflare One Free/Paid plans. Confirm seats, posture, logging and retention in the intended subscription; a website Enterprise plan is not the prerequisite for basic Access.","Use a supported cloudflared release and record its version during rehearsal. Confirm connector DNS/outbound connectivity and protect its credentials. The origin certificate must cover originServerName and chain to a trusted CA."]}' AND r.body_json IS '{"prerequisites":["Record the exact staging host, origin service/TLS name, Tunnel UUID, credential-file location, Access team name and application AUD. None of the example values is an account credential.","Create and review the exact-host Access policy before routing public traffic. Inventory alternate origin ports/hostnames so they cannot bypass the identity boundary."],"steps":["From the connector host, verify that the origin answers on the intended HTTPS port and presents the correct certificate. If it uses a private CA, configure the documented caPool rather than disabling verification.","Replace every uppercase placeholder in config.yml. Use the actual team name, not the full cloudflareaccess.com domain. Pin the expected application AUD; JWT header presence alone is not verification.","Validate ingress and matching locally with the documented cloudflared commands, using this configuration file. The final rule must not proxy unmatched hostnames. These checks do not test the IdP, live JWT validation or origin reachability.","With owner approval, route only the staging hostname to the intended Tunnel using the documented DNS procedure for your zone setup. Start the reviewed connector configuration and retain origin inbound restrictions.","Test allowed, denied, anonymous and alternate-origin paths before considering a separately approved production change. An Access login is not application-level permission to every resource."],"artifacts":[{"kind":"code","language":"yaml","filename":"config.yml","purpose":"Template for a locally managed staging Tunnel only. Replace placeholders; use the actual origin TLS name. Do not commit real credentials or disable TLS verification.","code":"tunnel: REPLACE_TUNNEL_UUID\ncredentials-file: /private/REPLACE_TUNNEL_UUID.json\ningress:\n  - hostname: app.example.com\n    service: https://127.0.0.1:8443\n    originRequest:\n      originServerName: origin.example.com\n      access:\n        required: true\n        teamName: REPLACE_TEAM_NAME\n        audTag:\n          - REPLACE_APPLICATION_AUD\n  - service: http_status:404"},{"kind":"warning","text":"Do not recover from a policy or TLS failure by opening the origin, adding an Access Bypass policy, or setting noTLSVerify. Fix the specific identity, audience, certificate or route problem."}],"validation":["An allowed browser user reaches the expected application; an out-of-policy user and a fresh anonymous session cannot obtain its protected content.","Invalid, absent and wrong-audience JWTs fail at the configured verification layer. Confirm the connector is running the reviewed configuration, not an old service configuration.","Unmatched hostnames hit the non-proxying catch-all; alternate hostnames/direct IPs cannot bypass origin restrictions.","Exercise connector loss and origin TLS/name failures only in the approved staging scope. Confirm the independent recovery path still works."],"rollback":["Restore the previously reviewed staging route/configuration or remove the new staging route. Keep origin restrictions and the Access policy in place.","Recover through the independent authenticated management path. Re-run allow/deny/bypass checks before restoring traffic; do not convert availability failures into authentication bypasses."]}' AND r.evidence IS 'public-docs' AND r.maturity IS 'ga' AND r.modified_at IS '2026-10-30' AND r.fact_verified_at IS '2026-10-30' AND r.review_due_at IS '2027-01-30' AND e.legacy_practice_id IS NULL AND e.published_revision_id = 810001 AND json_extract(r.lifecycle_json, '$.state') = 'active' AND json_extract(r.lifecycle_json, '$.reason') IS NULL AND json_extract(r.lifecycle_json, '$.supersededBy') IS NULL AND (SELECT COUNT(*) FROM CatalogRevisionTaxa WHERE revision_id = 810001) = 4 AND (SELECT COUNT(*) FROM CatalogRevisionSources WHERE revision_id = 810001) = 5 AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810001 AND kind = 'family' AND slug = 'cloudflare-one') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810001 AND kind = 'product' AND slug = 'access') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810001 AND kind = 'product' AND slug = 'tunnel') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810001 AND kind = 'outcome' AND slug = 'connect-private-applications') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810001 AND position = 0 AND url = 'https://developers.cloudflare.com/cloudflare-one/access-controls/applications/http-apps/self-hosted-public-app/' AND title = 'Access self-hosted public applications') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810001 AND position = 1 AND url = 'https://developers.cloudflare.com/tunnel/reference/origin-parameters/' AND title = 'Origin TLS and Protect with Access parameters') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810001 AND position = 2 AND url = 'https://developers.cloudflare.com/tunnel/features/locally-managed-tunnels/configuration-file/' AND title = 'Local configuration, ingress validation and matching') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810001 AND position = 3 AND url = 'https://developers.cloudflare.com/tunnel/troubleshooting/https-origins/' AND title = 'Verified HTTPS origins') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810001 AND position = 4 AND url = 'https://developers.cloudflare.com/cloudflare-one/' AND title = 'Cloudflare One plans and account limits'))) OR (NOT EXISTS (SELECT 1 FROM CatalogEntries WHERE practice_id = 810001) AND EXISTS (SELECT 1 FROM sqlite_sequence WHERE name IN ('BestPractices', 'CatalogEntries') AND seq >= 810001));
INSERT INTO CatalogEntries (practice_id) SELECT 0 WHERE ((EXISTS (SELECT 1 FROM CatalogEntries WHERE practice_id = 810002) OR EXISTS (SELECT 1 FROM CatalogRevisions WHERE revision_id = 810002 OR practice_id = 810002)) AND NOT EXISTS (SELECT 1 FROM CatalogEntries e JOIN CatalogRevisions r ON r.revision_id = e.published_revision_id JOIN CatalogPublications p ON p.practice_id = e.practice_id AND p.revision_id = r.revision_id WHERE e.practice_id = 810002 AND r.schema_version IS '1' AND r.content_type IS 'implementation-guide' AND r.title IS 'Diagnose a Tunnel 502 without weakening Access or origin TLS' AND r.summary IS 'Separate a disconnected Tunnel from a connected connector that cannot reach its origin. Diagnose from the connector host, change one scoped setting, and verify both availability and denied access.' AND r.primary_family IS 'cloudflare-one' AND r.applicability_json IS '{"requires":["An owned HTTP(S) Tunnel route, authorized read access to connector status/logs and an authenticated management path independent of the broken application."],"excludes":["Not every 502 comes from Tunnel. First establish that the response/logs identify cloudflared origin reachability rather than the origin application''s own 502.","Do not use this procedure to change third-party routes or conduct an unapproved production outage drill."],"dependencies":["Tunnel transport and Access authorization are separate. Confirm the account''s logging/support entitlements; this procedure does not require or promise a particular paid log-retention feature.","Record cloudflared version and local versus remote management mode. Read configuration from the actual connector service, not an unrelated local file."]}' AND r.body_json IS '{"variant":"operational-runbook","task":"Restore the intended application path while retaining Access, application authorization, verified origin TLS and origin inbound restrictions. Read-only diagnosis is not permission to mutate production.","symptoms":["A Tunnel response reports 502 and inability to reach the origin service while the connector remains connected.","Error 1033 instead indicates no available Tunnel connection; follow connector/outbound connectivity diagnosis before changing origin TLS."],"diagnostics":["Record the affected host/path, time, error class and scope without copying tokens, credential files or private logs to a public ticket. Compare with a known-good allowed session and preserve the denied-user test.","Read connector status and error logs. Separate connection refused, wrong protocol/port, DNS failure and certificate-name/trust errors; a connected Tunnel does not prove origin health.","From the same host/container/network namespace as cloudflared, test the configured service''s DNS, listener, protocol and TLS name using a safe read-only endpoint. A successful test from an operator laptop is not connector reachability evidence.","Compare the actual route/service and originServerName/CA settings with the last known-good configuration. For multiple replicas, verify every connector can reach the required origin; replicas are not health-aware origin steering."],"safeChanges":["Obtain approval for the exact route/connector/origin fix and record its previous setting. Repair a stopped origin service or the specific protocol, port, DNS, TLS name or CA trust mismatch.","Change one scoped setting at a time and retest. Keep certificate verification enabled and retain the correct Access application audience; do not broadly bypass Access or expose a public origin port."],"recovery":["If the cause is uncertain or the scoped repair fails, restore the last known-good setting and escalate with redacted error class, time, connector version and reproduction scope.","Use the independent management path. For total connector loss, restore approved outbound connectivity/connector service. Do not disable healthy replicas or promise instantaneous failover."],"successCriteria":["An allowed user reaches the intended application through the expected hostname with valid origin TLS and no recurring connector-origin error.","Denied and anonymous users still cannot obtain protected content, and direct-IP/alternate-hostname bypass tests still fail.","All intended connectors reach the origin; application-path monitoring, not connector status alone, confirms recovery."],"rollback":["Revert only the approved route/service/TLS change to its recorded prior value. Preserve authentication and origin restrictions throughout.","If no safe working configuration exists, keep the route unavailable rather than creating an unauthenticated recovery path; escalate to the application/network owner."]}' AND r.evidence IS 'public-docs' AND r.maturity IS 'ga' AND r.modified_at IS '2026-10-30' AND r.fact_verified_at IS '2026-10-30' AND r.review_due_at IS '2027-01-30' AND e.legacy_practice_id IS NULL AND e.published_revision_id = 810002 AND json_extract(r.lifecycle_json, '$.state') = 'active' AND json_extract(r.lifecycle_json, '$.reason') IS NULL AND json_extract(r.lifecycle_json, '$.supersededBy') IS NULL AND (SELECT COUNT(*) FROM CatalogRevisionTaxa WHERE revision_id = 810002) = 5 AND (SELECT COUNT(*) FROM CatalogRevisionSources WHERE revision_id = 810002) = 4 AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810002 AND kind = 'family' AND slug = 'cloudflare-one') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810002 AND kind = 'product' AND slug = 'access') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810002 AND kind = 'product' AND slug = 'tunnel') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810002 AND kind = 'outcome' AND slug = 'connect-private-applications') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810002 AND kind = 'outcome' AND slug = 'operate-the-platform') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810002 AND position = 0 AND url = 'https://developers.cloudflare.com/tunnel/troubleshooting/' AND title = 'Tunnel 1033 and origin-side 502 troubleshooting') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810002 AND position = 1 AND url = 'https://developers.cloudflare.com/tunnel/troubleshooting/https-origins/' AND title = 'Origin certificate, SNI and CA troubleshooting') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810002 AND position = 2 AND url = 'https://developers.cloudflare.com/tunnel/reference/origin-parameters/' AND title = 'Origin and Access validation parameters') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810002 AND position = 3 AND url = 'https://developers.cloudflare.com/tunnel/concepts/routing/' AND title = 'Tunnel routing and replicas'))) OR (NOT EXISTS (SELECT 1 FROM CatalogEntries WHERE practice_id = 810002) AND EXISTS (SELECT 1 FROM sqlite_sequence WHERE name IN ('BestPractices', 'CatalogEntries') AND seq >= 810002));
INSERT INTO CatalogEntries (practice_id) SELECT 0 WHERE ((EXISTS (SELECT 1 FROM CatalogEntries WHERE practice_id = 810003) OR EXISTS (SELECT 1 FROM CatalogRevisions WHERE revision_id = 810003 OR practice_id = 810003)) AND NOT EXISTS (SELECT 1 FROM CatalogEntries e JOIN CatalogRevisions r ON r.revision_id = e.published_revision_id JOIN CatalogPublications p ON p.practice_id = e.practice_id AND p.revision_id = r.revision_id WHERE e.practice_id = 810003 AND r.schema_version IS '1' AND r.content_type IS 'implementation-guide' AND r.title IS 'Read D1 summaries with bounded keyset pagination' AND r.summary IS 'Use a parameterized, bounded repository read rather than downloading every body. A first-primary session starts from current primary data; it does not invalidate an external cache.' AND r.primary_family IS 'developer-platform' AND r.applicability_json IS '{"requires":["A TypeScript Worker with generated Env and a local DB binding. Use a disposable local database for the independent schema below.","Authenticate/authorize private reads before the repository and expose only the intended public columns. Bound and validate query input at the HTTP boundary."],"excludes":["This is a repository example, not a full HTTP handler, public cursor protocol or snapshot-isolated multi-request export.","Do not apply this schema to the catalog database or cache private query results in a shared cache."],"dependencies":["D1 is available on Workers Free and Paid with different row, storage and database limits. Index maintenance also costs writes; verify current workload/pricing rather than relying on website-plan names.","first-primary routes a session''s first query to the primary. Sequential consistency within that session does not freeze the database across independently paginated HTTP requests."]}' AND r.body_json IS '{"prerequisites":["Generate Env from the actual Wrangler bindings. Do not set remote: true on a development D1 binding.","Use nonnegative safe integer cursors and a positive limit no larger than 50. Decide whether concurrent changes are acceptable; a frozen export requires a separate snapshot/version design."],"steps":["Apply schema.sql only to a new disposable local database, then insert representative published and unpublished rows.","Call listSummaries after validating the HTTP request and authorization. It returns only IDs/titles, not bodies or unpublished entries.","Use the last returned ID as the next cursor; stop on an empty page. Keep a stable ascending ID order. Do not silently truncate a complete export at one page.","Inspect EXPLAIN QUERY PLAN and row-read metadata on representative data. An index is not proof of lower real workload cost; run PRAGMA optimize after index changes.","If a public cache is later added, normalize the cursor/limit before caching and invalidate it after writes. first-primary neither purges a cache nor promises global read-after-write visibility through it."],"artifacts":[{"kind":"code","language":"sql","filename":"schema.sql","purpose":"Independent local teaching schema, not a migration for this catalog. The composite index supports published status plus ordered cursor reads.","code":"CREATE TABLE Articles (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  title TEXT NOT NULL,\n  body TEXT NOT NULL,\n  published INTEGER NOT NULL DEFAULT 0 CHECK (published IN (0, 1))\n);\nCREATE INDEX articles_published_id ON Articles(published, id);\nPRAGMA optimize;"},{"kind":"code","language":"typescript","filename":"summaries.ts","purpose":"Bounded public-column repository only. The caller owns HTTP parsing, authorization, response headers, cursor encoding and any cache policy.","code":"export async function listSummaries(\n  db: Env[''DB''], after: number, limit: number,\n): Promise<{ id: number; title: string }[]> {\n  if (!Number.isSafeInteger(after) || after < 0 ||\n      !Number.isSafeInteger(limit) || limit < 1 || limit > 50) {\n    throw new RangeError(''Invalid cursor or page size'');\n  }\n  const session = db.withSession(''first-primary'');\n  const result = await session.prepare(\n    ''SELECT id, title FROM Articles WHERE published = 1 AND id > ? ORDER BY id LIMIT ?'',\n  ).bind(after, limit).all<{ id: number; title: string }>();\n  return result.results;\n}"}],"validation":["Insert published and unpublished records with large bodies; verify only published IDs/titles are returned and bodies are never selected.","Traverse pages of size 1 and 50 without duplicates on a stable dataset; verify an empty terminal page and reject negative, fractional, unsafe and oversized cursor/limit inputs.","Test concurrent insert/update behavior explicitly: new higher IDs may appear later and unpublishing changes membership. Do not call this a frozen snapshot.","Rehearse binding/schema errors and private/public HTTP cache headers separately. Local tests do not prove production replica or cache behavior."],"rollback":["Roll back repository/HTTP code without dropping application rows or resetting identity sequences.","Review removal of any added index separately; preserve database data and verify the previous query path before restoring traffic."]}' AND r.evidence IS 'public-docs' AND r.maturity IS 'ga' AND r.modified_at IS '2026-10-30' AND r.fact_verified_at IS '2026-10-30' AND r.review_due_at IS '2027-01-30' AND e.legacy_practice_id IS NULL AND e.published_revision_id = 810003 AND json_extract(r.lifecycle_json, '$.state') = 'active' AND json_extract(r.lifecycle_json, '$.reason') IS NULL AND json_extract(r.lifecycle_json, '$.supersededBy') IS NULL AND (SELECT COUNT(*) FROM CatalogRevisionTaxa WHERE revision_id = 810003) = 4 AND (SELECT COUNT(*) FROM CatalogRevisionSources WHERE revision_id = 810003) = 5 AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810003 AND kind = 'family' AND slug = 'developer-platform') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810003 AND kind = 'product' AND slug = 'd1') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810003 AND kind = 'product' AND slug = 'workers') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810003 AND kind = 'outcome' AND slug = 'build-reliable-services') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810003 AND position = 0 AND url = 'https://developers.cloudflare.com/d1/worker-api/d1-database/' AND title = 'D1 bindings, prepare, bind and sessions') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810003 AND position = 1 AND url = 'https://developers.cloudflare.com/d1/best-practices/read-replication/' AND title = 'Session consistency and first-primary') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810003 AND position = 2 AND url = 'https://developers.cloudflare.com/d1/best-practices/use-indexes/' AND title = 'D1 indexes and query plans') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810003 AND position = 3 AND url = 'https://developers.cloudflare.com/d1/platform/pricing/' AND title = 'D1 plans and row-based costs') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810003 AND position = 4 AND url = 'https://developers.cloudflare.com/workers/best-practices/workers-best-practices/' AND title = 'Workers generated types and bounded I/O'))) OR (NOT EXISTS (SELECT 1 FROM CatalogEntries WHERE practice_id = 810003) AND EXISTS (SELECT 1 FROM sqlite_sequence WHERE name IN ('BestPractices', 'CatalogEntries') AND seq >= 810003));
INSERT INTO CatalogEntries (practice_id) SELECT 0 WHERE ((EXISTS (SELECT 1 FROM CatalogEntries WHERE practice_id = 810004) OR EXISTS (SELECT 1 FROM CatalogRevisions WHERE revision_id = 810004 OR practice_id = 810004)) AND NOT EXISTS (SELECT 1 FROM CatalogEntries e JOIN CatalogRevisions r ON r.revision_id = e.published_revision_id JOIN CatalogPublications p ON p.practice_id = e.practice_id AND p.revision_id = r.revision_id WHERE e.practice_id = 810004 AND r.schema_version IS '1' AND r.content_type IS 'implementation-guide' AND r.title IS 'Recover an uncertain D1 write without creating a duplicate' AND r.summary IS 'Treat a timeout or lost response as an unknown commit outcome. Recover through a durable actor-scoped receipt when the application supports it, and stop instead of blindly retrying an arbitrary write.' AND r.primary_family IS 'developer-platform' AND r.applicability_json IS '{"requires":["Authorized application/database operators, a known operation contract and an independent authenticated recovery path.","For automatic replay, an existing application-idempotent transaction that commits business data and a durable actor/operation/key receipt together, with payload-conflict checks."],"excludes":["No receipt or proven idempotent business operation means no automatic write replay. This runbook cannot retrofit exactly-once delivery after an incident.","A D1 receipt does not atomically cover email, third-party APIs or cache purges. Investigate each external side effect independently."],"dependencies":["Record the deployed application/operation version and D1 binding. Keep original operation keys private; do not log tokens, raw keys, request bodies or recovery bookmarks.","D1 Free/Paid quotas differ. Quota exhaustion, syntax/constraint errors and transient faults need different responses. Confirm backup/Time Travel availability and retention separately; a public seed is not a recovery backup."]}' AND r.body_json IS '{"variant":"operational-runbook","task":"Resolve an uncertain commit through the application''s existing durable operation contract, without deleting receipts, changing retry keys or rerunning unrelated side effects.","symptoms":["A client or Worker loses the response after issuing a write, or an application timeout fires before D1 returns.","The application may have committed despite the error. Promise.race with a timer does not cancel the D1 query; binding methods do not accept a per-call AbortSignal."],"diagnostics":["Pause manual resubmissions. Record a redacted incident correlation/time and deployed version; preserve the original actor, key, normalized payload and operation namespace in private recovery tooling.","Read the actual error object through approved private observability. Separate deterministic schema/constraint failures and Free-plan daily limits from documented retryable faults. Do not retry quota exhaustion in a tight loop.","Read the durable receipt through the supported application recovery path using a first-primary session. Compare the normalized payload digest and actor/operation scope; a receipt for another actor or operation is not the result.","If the receipt exists and agrees, verify its referenced business row. If it conflicts, return the documented conflict and investigate; never delete the receipt or rotate the key to force success."],"safeChanges":["Only when the existing endpoint is proven application-idempotent, perform a bounded unchanged retry with the same actor/key/payload. A missing receipt during an in-flight request is not proof of rollback; the transaction''s uniqueness guard must arbitrate concurrency.","If there is no durable idempotent contract, stop automatic replay and have the owner reconcile business state before an approved compensating action. Fix deterministic errors separately, not by broad retry.","After confirmed creation or replay, use the application''s supported cache-purge/recovery path if required. A purge failure does not roll back D1; do not reinsert data to repair a cache."],"recovery":["Escalate inconsistent receipt/business state or unknown external side effects to the application owner. Keep evidence private and preserve receipts and sequence high-water marks.","Database restore is a separately approved last resort after a fresh private backup and rehearsal on an isolated copy. A restore can roll back unrelated successful writes and does not roll back external effects or clear caches."],"successCriteria":["Unchanged replay returns the original stable result with one business row and one durable receipt; changed data with the same key is a conflict.","Concurrent recovery and simulated lost-commit responses converge without duplicate rows; forced receipt failure rolls back the business insert in the local rehearsal.","Required purge/recovery is attempted independently; actual public representations are checked after an approved deployment. Browser caches may remain fresh after an edge purge."],"rollback":["Revert application code only within a compatible operation namespace/payload/receipt contract. Never drop receipts or reset identity sequences during rollback.","If compatibility or business outcome is uncertain, pause writes and reconcile using the private recovery plan; do not restore from the public catalog seed."]}' AND r.evidence IS 'public-docs' AND r.maturity IS 'ga' AND r.modified_at IS '2026-10-30' AND r.fact_verified_at IS '2026-10-30' AND r.review_due_at IS '2027-01-30' AND e.legacy_practice_id IS NULL AND e.published_revision_id = 810004 AND json_extract(r.lifecycle_json, '$.state') = 'active' AND json_extract(r.lifecycle_json, '$.reason') IS NULL AND json_extract(r.lifecycle_json, '$.supersededBy') IS NULL AND (SELECT COUNT(*) FROM CatalogRevisionTaxa WHERE revision_id = 810004) = 5 AND (SELECT COUNT(*) FROM CatalogRevisionSources WHERE revision_id = 810004) = 5 AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810004 AND kind = 'family' AND slug = 'developer-platform') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810004 AND kind = 'product' AND slug = 'd1') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810004 AND kind = 'product' AND slug = 'workers') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810004 AND kind = 'outcome' AND slug = 'build-reliable-services') AND EXISTS (SELECT 1 FROM CatalogRevisionTaxa WHERE revision_id = 810004 AND kind = 'outcome' AND slug = 'operate-the-platform') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810004 AND position = 0 AND url = 'https://developers.cloudflare.com/d1/observability/debug-d1/' AND title = 'D1 errors and non-cancelling timeout behavior') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810004 AND position = 1 AND url = 'https://developers.cloudflare.com/d1/best-practices/retry-queries/' AND title = 'Retry only application-idempotent writes') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810004 AND position = 2 AND url = 'https://developers.cloudflare.com/d1/worker-api/d1-database/' AND title = 'Transactional batch and sessions') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810004 AND position = 3 AND url = 'https://developers.cloudflare.com/d1/reference/time-travel/' AND title = 'Private database recovery and retention') AND EXISTS (SELECT 1 FROM CatalogRevisionSources WHERE revision_id = 810004 AND position = 4 AND url = 'https://developers.cloudflare.com/d1/platform/pricing/' AND title = 'Plan-dependent row limits'))) OR (NOT EXISTS (SELECT 1 FROM CatalogEntries WHERE practice_id = 810004) AND EXISTS (SELECT 1 FROM sqlite_sequence WHERE name IN ('BestPractices', 'CatalogEntries') AND seq >= 810004));
INSERT INTO CatalogEntries (practice_id) SELECT 810001 WHERE NOT EXISTS (SELECT 1 FROM CatalogEntries WHERE practice_id = 810001);
INSERT INTO CatalogRevisions (revision_id, practice_id, schema_version, content_type, title, summary, primary_family, applicability_json, body_json, evidence, maturity, modified_at, fact_verified_at, review_due_at) SELECT 810001, 810001, '1', 'implementation-guide', 'Stage an Access-protected Tunnel hostname without opening the origin', 'Build a single-host browser-access rehearsal: narrow Access policy, connector JWT validation, verified origin TLS, explicit ingress, and a deny-by-default catch-all.', 'cloudflare-one', '{"requires":["An owner-approved staging hostname, a locally managed named Tunnel, and a connector host that can reach the intended HTTPS origin.","An Access self-hosted public application for the exact hostname, a tested identity provider, and a narrowly scoped Allow policy. Keep an independent authenticated recovery path."],"excludes":["This is browser access through a public hostname, not private-IP routing or a site-to-site VPN. APIs need a separately selected supported authentication flow.","Do not mix a locally managed configuration file with a remotely managed tunnel configuration. The file is a template, not an instruction to change production."],"dependencies":["Access has separate Cloudflare One Free/Paid plans. Confirm seats, posture, logging and retention in the intended subscription; a website Enterprise plan is not the prerequisite for basic Access.","Use a supported cloudflared release and record its version during rehearsal. Confirm connector DNS/outbound connectivity and protect its credentials. The origin certificate must cover originServerName and chain to a trusted CA."]}', '{"prerequisites":["Record the exact staging host, origin service/TLS name, Tunnel UUID, credential-file location, Access team name and application AUD. None of the example values is an account credential.","Create and review the exact-host Access policy before routing public traffic. Inventory alternate origin ports/hostnames so they cannot bypass the identity boundary."],"steps":["From the connector host, verify that the origin answers on the intended HTTPS port and presents the correct certificate. If it uses a private CA, configure the documented caPool rather than disabling verification.","Replace every uppercase placeholder in config.yml. Use the actual team name, not the full cloudflareaccess.com domain. Pin the expected application AUD; JWT header presence alone is not verification.","Validate ingress and matching locally with the documented cloudflared commands, using this configuration file. The final rule must not proxy unmatched hostnames. These checks do not test the IdP, live JWT validation or origin reachability.","With owner approval, route only the staging hostname to the intended Tunnel using the documented DNS procedure for your zone setup. Start the reviewed connector configuration and retain origin inbound restrictions.","Test allowed, denied, anonymous and alternate-origin paths before considering a separately approved production change. An Access login is not application-level permission to every resource."],"artifacts":[{"kind":"code","language":"yaml","filename":"config.yml","purpose":"Template for a locally managed staging Tunnel only. Replace placeholders; use the actual origin TLS name. Do not commit real credentials or disable TLS verification.","code":"tunnel: REPLACE_TUNNEL_UUID\ncredentials-file: /private/REPLACE_TUNNEL_UUID.json\ningress:\n  - hostname: app.example.com\n    service: https://127.0.0.1:8443\n    originRequest:\n      originServerName: origin.example.com\n      access:\n        required: true\n        teamName: REPLACE_TEAM_NAME\n        audTag:\n          - REPLACE_APPLICATION_AUD\n  - service: http_status:404"},{"kind":"warning","text":"Do not recover from a policy or TLS failure by opening the origin, adding an Access Bypass policy, or setting noTLSVerify. Fix the specific identity, audience, certificate or route problem."}],"validation":["An allowed browser user reaches the expected application; an out-of-policy user and a fresh anonymous session cannot obtain its protected content.","Invalid, absent and wrong-audience JWTs fail at the configured verification layer. Confirm the connector is running the reviewed configuration, not an old service configuration.","Unmatched hostnames hit the non-proxying catch-all; alternate hostnames/direct IPs cannot bypass origin restrictions.","Exercise connector loss and origin TLS/name failures only in the approved staging scope. Confirm the independent recovery path still works."],"rollback":["Restore the previously reviewed staging route/configuration or remove the new staging route. Keep origin restrictions and the Access policy in place.","Recover through the independent authenticated management path. Re-run allow/deny/bypass checks before restoring traffic; do not convert availability failures into authentication bypasses."]}', 'public-docs', 'ga', '2026-10-30', '2026-10-30', '2027-01-30' WHERE NOT EXISTS (SELECT 1 FROM CatalogRevisions WHERE revision_id = 810001);
