INSERT INTO CatalogRevisions (revision_id, practice_id, schema_version, content_type, title, summary, primary_family, applicability_json, body_json, evidence, maturity, modified_at, fact_verified_at, review_due_at) SELECT 810002, 810002, '1', 'implementation-guide', 'Diagnose a Tunnel 502 without weakening Access or origin TLS', 'Separate a disconnected Tunnel from a connected connector that cannot reach its origin. Diagnose from the connector host, change one scoped setting, and verify both availability and denied access.', 'cloudflare-one', '{"requires":["An owned HTTP(S) Tunnel route, authorized read access to connector status/logs and an authenticated management path independent of the broken application."],"excludes":["Not every 502 comes from Tunnel. First establish that the response/logs identify cloudflared origin reachability rather than the origin application''s own 502.","Do not use this procedure to change third-party routes or conduct an unapproved production outage drill."],"dependencies":["Tunnel transport and Access authorization are separate. Confirm the account''s logging/support entitlements; this procedure does not require or promise a particular paid log-retention feature.","Record cloudflared version and local versus remote management mode. Read configuration from the actual connector service, not an unrelated local file."]}', '{"variant":"operational-runbook","task":"Restore the intended application path while retaining Access, application authorization, verified origin TLS and origin inbound restrictions. Read-only diagnosis is not permission to mutate production.","symptoms":["A Tunnel response reports 502 and inability to reach the origin service while the connector remains connected.","Error 1033 instead indicates no available Tunnel connection; follow connector/outbound connectivity diagnosis before changing origin TLS."],"diagnostics":["Record the affected host/path, time, error class and scope without copying tokens, credential files or private logs to a public ticket. Compare with a known-good allowed session and preserve the denied-user test.","Read connector status and error logs. Separate connection refused, wrong protocol/port, DNS failure and certificate-name/trust errors; a connected Tunnel does not prove origin health.","From the same host/container/network namespace as cloudflared, test the configured service''s DNS, listener, protocol and TLS name using a safe read-only endpoint. A successful test from an operator laptop is not connector reachability evidence.","Compare the actual route/service and originServerName/CA settings with the last known-good configuration. For multiple replicas, verify every connector can reach the required origin; replicas are not health-aware origin steering."],"safeChanges":["Obtain approval for the exact route/connector/origin fix and record its previous setting. Repair a stopped origin service or the specific protocol, port, DNS, TLS name or CA trust mismatch.","Change one scoped setting at a time and retest. Keep certificate verification enabled and retain the correct Access application audience; do not broadly bypass Access or expose a public origin port."],"recovery":["If the cause is uncertain or the scoped repair fails, restore the last known-good setting and escalate with redacted error class, time, connector version and reproduction scope.","Use the independent management path. For total connector loss, restore approved outbound connectivity/connector service. Do not disable healthy replicas or promise instantaneous failover."],"successCriteria":["An allowed user reaches the intended application through the expected hostname with valid origin TLS and no recurring connector-origin error.","Denied and anonymous users still cannot obtain protected content, and direct-IP/alternate-hostname bypass tests still fail.","All intended connectors reach the origin; application-path monitoring, not connector status alone, confirms recovery."],"rollback":["Revert only the approved route/service/TLS change to its recorded prior value. Preserve authentication and origin restrictions throughout.","If no safe working configuration exists, keep the route unavailable rather than creating an unauthenticated recovery path; escalate to the application/network owner."]}', 'public-docs', 'ga', '2026-10-30', '2026-10-30', '2027-01-30' WHERE NOT EXISTS (SELECT 1 FROM CatalogRevisions WHERE revision_id = 810002);
