INSERT INTO CatalogRevisions (revision_id, practice_id, schema_version, content_type, title, summary, primary_family, applicability_json, body_json, evidence, maturity, modified_at, fact_verified_at, review_due_at) SELECT 810003, 810003, '1', 'implementation-guide', 'Read D1 summaries with bounded keyset pagination', 'Use a parameterized, bounded repository read rather than downloading every body. A first-primary session starts from current primary data; it does not invalidate an external cache.', 'developer-platform', '{"requires":["A TypeScript Worker with generated Env and a local DB binding. Use a disposable local database for the independent schema below.","Authenticate/authorize private reads before the repository and expose only the intended public columns. Bound and validate query input at the HTTP boundary."],"excludes":["This is a repository example, not a full HTTP handler, public cursor protocol or snapshot-isolated multi-request export.","Do not apply this schema to the catalog database or cache private query results in a shared cache."],"dependencies":["D1 is available on Workers Free and Paid with different row, storage and database limits. Index maintenance also costs writes; verify current workload/pricing rather than relying on website-plan names.","first-primary routes a session''s first query to the primary. Sequential consistency within that session does not freeze the database across independently paginated HTTP requests."]}', '{"prerequisites":["Generate Env from the actual Wrangler bindings. Do not set remote: true on a development D1 binding.","Use nonnegative safe integer cursors and a positive limit no larger than 50. Decide whether concurrent changes are acceptable; a frozen export requires a separate snapshot/version design."],"steps":["Apply schema.sql only to a new disposable local database, then insert representative published and unpublished rows.","Call listSummaries after validating the HTTP request and authorization. It returns only IDs/titles, not bodies or unpublished entries.","Use the last returned ID as the next cursor; stop on an empty page. Keep a stable ascending ID order. Do not silently truncate a complete export at one page.","Inspect EXPLAIN QUERY PLAN and row-read metadata on representative data. An index is not proof of lower real workload cost; run PRAGMA optimize after index changes.","If a public cache is later added, normalize the cursor/limit before caching and invalidate it after writes. first-primary neither purges a cache nor promises global read-after-write visibility through it."],"artifacts":[{"kind":"code","language":"sql","filename":"schema.sql","purpose":"Independent local teaching schema, not a migration for this catalog. The composite index supports published status plus ordered cursor reads.","code":"CREATE TABLE Articles (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  title TEXT NOT NULL,\n  body TEXT NOT NULL,\n  published INTEGER NOT NULL DEFAULT 0 CHECK (published IN (0, 1))\n);\nCREATE INDEX articles_published_id ON Articles(published, id);\nPRAGMA optimize;"},{"kind":"code","language":"typescript","filename":"summaries.ts","purpose":"Bounded public-column repository only. The caller owns HTTP parsing, authorization, response headers, cursor encoding and any cache policy.","code":"export async function listSummaries(\n  db: Env[''DB''], after: number, limit: number,\n): Promise<{ id: number; title: string }[]> {\n  if (!Number.isSafeInteger(after) || after < 0 ||\n      !Number.isSafeInteger(limit) || limit < 1 || limit > 50) {\n    throw new RangeError(''Invalid cursor or page size'');\n  }\n  const session = db.withSession(''first-primary'');\n  const result = await session.prepare(\n    ''SELECT id, title FROM Articles WHERE published = 1 AND id > ? ORDER BY id LIMIT ?'',\n  ).bind(after, limit).all<{ id: number; title: string }>();\n  return result.results;\n}"}],"validation":["Insert published and unpublished records with large bodies; verify only published IDs/titles are returned and bodies are never selected.","Traverse pages of size 1 and 50 without duplicates on a stable dataset; verify an empty terminal page and reject negative, fractional, unsafe and oversized cursor/limit inputs.","Test concurrent insert/update behavior explicitly: new higher IDs may appear later and unpublishing changes membership. Do not call this a frozen snapshot.","Rehearse binding/schema errors and private/public HTTP cache headers separately. Local tests do not prove production replica or cache behavior."],"rollback":["Roll back repository/HTTP code without dropping application rows or resetting identity sequences.","Review removal of any added index separately; preserve database data and verify the previous query path before restoring traffic."]}', 'public-docs', 'ga', '2026-10-30', '2026-10-30', '2027-01-30' WHERE NOT EXISTS (SELECT 1 FROM CatalogRevisions WHERE revision_id = 810003);
