INSERT INTO CatalogRevisions (revision_id, practice_id, schema_version, content_type, title, summary, primary_family, applicability_json, body_json, evidence, maturity, modified_at, fact_verified_at, review_due_at) SELECT 810004, 810004, '1', 'implementation-guide', 'Recover an uncertain D1 write without creating a duplicate', 'Treat a timeout or lost response as an unknown commit outcome. Recover through a durable actor-scoped receipt when the application supports it, and stop instead of blindly retrying an arbitrary write.', 'developer-platform', '{"requires":["Authorized application/database operators, a known operation contract and an independent authenticated recovery path.","For automatic replay, an existing application-idempotent transaction that commits business data and a durable actor/operation/key receipt together, with payload-conflict checks."],"excludes":["No receipt or proven idempotent business operation means no automatic write replay. This runbook cannot retrofit exactly-once delivery after an incident.","A D1 receipt does not atomically cover email, third-party APIs or cache purges. Investigate each external side effect independently."],"dependencies":["Record the deployed application/operation version and D1 binding. Keep original operation keys private; do not log tokens, raw keys, request bodies or recovery bookmarks.","D1 Free/Paid quotas differ. Quota exhaustion, syntax/constraint errors and transient faults need different responses. Confirm backup/Time Travel availability and retention separately; a public seed is not a recovery backup."]}', '{"variant":"operational-runbook","task":"Resolve an uncertain commit through the application''s existing durable operation contract, without deleting receipts, changing retry keys or rerunning unrelated side effects.","symptoms":["A client or Worker loses the response after issuing a write, or an application timeout fires before D1 returns.","The application may have committed despite the error. Promise.race with a timer does not cancel the D1 query; binding methods do not accept a per-call AbortSignal."],"diagnostics":["Pause manual resubmissions. Record a redacted incident correlation/time and deployed version; preserve the original actor, key, normalized payload and operation namespace in private recovery tooling.","Read the actual error object through approved private observability. Separate deterministic schema/constraint failures and Free-plan daily limits from documented retryable faults. Do not retry quota exhaustion in a tight loop.","Read the durable receipt through the supported application recovery path using a first-primary session. Compare the normalized payload digest and actor/operation scope; a receipt for another actor or operation is not the result.","If the receipt exists and agrees, verify its referenced business row. If it conflicts, return the documented conflict and investigate; never delete the receipt or rotate the key to force success."],"safeChanges":["Only when the existing endpoint is proven application-idempotent, perform a bounded unchanged retry with the same actor/key/payload. A missing receipt during an in-flight request is not proof of rollback; the transaction''s uniqueness guard must arbitrate concurrency.","If there is no durable idempotent contract, stop automatic replay and have the owner reconcile business state before an approved compensating action. Fix deterministic errors separately, not by broad retry.","After confirmed creation or replay, use the application''s supported cache-purge/recovery path if required. A purge failure does not roll back D1; do not reinsert data to repair a cache."],"recovery":["Escalate inconsistent receipt/business state or unknown external side effects to the application owner. Keep evidence private and preserve receipts and sequence high-water marks.","Database restore is a separately approved last resort after a fresh private backup and rehearsal on an isolated copy. A restore can roll back unrelated successful writes and does not roll back external effects or clear caches."],"successCriteria":["Unchanged replay returns the original stable result with one business row and one durable receipt; changed data with the same key is a conflict.","Concurrent recovery and simulated lost-commit responses converge without duplicate rows; forced receipt failure rolls back the business insert in the local rehearsal.","Required purge/recovery is attempted independently; actual public representations are checked after an approved deployment. Browser caches may remain fresh after an edge purge."],"rollback":["Revert application code only within a compatible operation namespace/payload/receipt contract. Never drop receipts or reset identity sequences during rollback.","If compatibility or business outcome is uncertain, pause writes and reconcile using the private recovery plan; do not restore from the public catalog seed."]}', 'public-docs', 'ga', '2026-10-30', '2026-10-30', '2027-01-30' WHERE NOT EXISTS (SELECT 1 FROM CatalogRevisions WHERE revision_id = 810004);
